#include <iostream>
#include <cstddef>

int main() {
    int values[] = {100, 200, 300, 400, 500};
    int* startPtr = values;       // points to values[0]
    int* endPtr = values + 4;     // points to values[4]

    std::ptrdiff_t diff = endPtr - startPtr;
    std::cout << "Difference in elements: " << diff << "\n";

    // Generic void* demonstration
    void* genericPtr = &values[2]; // implicit conversion to void*
    // Convert back using static_cast before dereferencing
    int* intPtr = static_cast<int*>(genericPtr);
    std::cout << "Value via casted void*: " << *intPtr << "\n";

    // Comparison
    if (startPtr < endPtr) {
        std::cout << "startPtr comes before endPtr\n";
    }

    return 0;
}

#include <iostream>

int main() {
    int b[] = {10, 20, 30, 40};
    int* bPtr = b;

    std::cout << "1. Array subscript:\n";
    for (std::size_t i = 0; i < 4; ++i) {
        std::cout << "b[" << i << "] = " << b[i] << "\n";
    }

    std::cout << "\n2. Array pointer/offset:\n";
    for (std::size_t offset1 = 0; offset1 < 4; ++offset1) {
        std::cout << "*(b + " << offset1 << ") = " << *(b + offset1) << "\n";
    }

    std::cout << "\n3. Pointer subscript:\n";
    for (std::size_t j = 0; j < 4; ++j) {
        std::cout << "bPtr[" << j << "] = " << bPtr[j] << "\n";
    }

    std::cout << "\n4. Pointer pointer/offset:\n";
    for (std::size_t offset2 = 0; offset2 < 4; ++offset2) {
        std::cout << "*(bPtr + " << offset2 << ") = " << *(bPtr + offset2) << "\n";
    }

    return 0;
}
